def truncate_name(name: str) -> str:
    """ Given a name which is splitted in several words separated by spaces,
    return the word with largest length and truncate its content at the
    last character. Remove spaces before and after returned word.

    >>> truncate_name('Marta Dávid')
    'Mart'
