def sum_interleave(numbers: List[int]) -> int:
    """ Use recursive helper function `sum_interleave` to calculate the sum of numbers in `numbers`.
        The sum of numbers is equal to the first number in `numbers` plus the sum of remaining numbers in `numbers`.
    """
    if len(numbers) == 1:
        return numbers[0]
    return numbers[0] + sum_interleave(numbers[1:])


def sum_alternate(numbers: List[int]) -> int:
    """ Use recursive helper function `sum_alternate` to calculate the sum of numbers in `numbers`.
        The sum of numbers is equal to the alternating sum of the remaining numbers in `numbers`.
    """
    if len(numbers) == 0:
        return 0
    return numbers[-1] - sum_alternate(numbers[:-1])


def count_list_elements(numbers: List[int]) -> int:
    """ Use recursive helper function `count_list_elements` to count the number of elements in `numbers`.
    """
    if len(numbers) == 0:
        return 0
    return 1 + count_list_elements(numbers[1:])


