def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Median.
    Median is the center value of the dataset:
    For odd number of elements, it's the value of the middle element
    Median is the average of the middle two values for even number of elements
    """
    numbers.sort()
    center = len(numbers) // 2
    if len(numbers) % 2 == 0:
        return sum(numbers[center - 1: center + 1]) / 2
    else:
        return numbers[center]


def mode(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Mode.
    Mode is the value that occurs the most.
    """
    max_num = -1
    max_num_count = 0
    for number in numbers:
        count = 0
        for num in numbers:
            if num == number:
                count += 1
        if count > max_num_count:
            max_num = number
            max_num_count = count
    return max_num

